150	/// only for columns that are missing. Safe to call on both fresh and old databases.
151	fn migrate_tasks_columns(conn: &rusqlite::Connection) -> rusqlite::Result<()> {
152	    // Collect existing column names for `tasks`.
153	    let mut stmt = conn.prepare("PRAGMA table_info(tasks)")?;
154	    let existing: HashSet<String> = stmt
155	        .query_map([], |row| row.get::<_, String>(1))?
156	        .collect::<rusqlite::Result<_>>()?;
157	
158	    let additive = [
159	        ("input", "TEXT NOT NULL DEFAULT ''"),
160	        ("workflow_spec_json", "TEXT"),
161	        ("resume_attempts", "INTEGER NOT NULL DEFAULT 0"),
162	        ("last_resume_ms", "INTEGER"),
163	        ("session_cwd", "TEXT"),
164	        ("last_event_seq", "INTEGER NOT NULL DEFAULT 0"),
165	        ("terminal_seq", "INTEGER"),
166	        ("journal_complete_from_birth", "INTEGER NOT NULL DEFAULT 0"),
167	    ];
168	    for (col, def) in additive {
169	        if !existing.contains(col) {
170	            conn.execute_batch(&format!("ALTER TABLE tasks ADD COLUMN {col} {def};"))?;
171	        }
172	    }
173	
174	    // Collect existing column names for `task_node_checkpoints`.
175	    let mut stmt2 = conn.prepare("PRAGMA table_info(task_node_checkpoints)")?;
176	    let cp_existing: HashSet<String> = stmt2
177	        .query_map([], |row| row.get::<_, String>(1))?
178	        .collect::<rusqlite::Result<_>>()?;
179	    if !cp_existing.contains("seq") {
180	        conn.execute_batch("ALTER TABLE task_node_checkpoints ADD COLUMN seq INTEGER;")?;
181	    }
182	    if !cp_existing.contains("usage_json") {
183	        conn.execute_batch("ALTER TABLE task_node_checkpoints ADD COLUMN usage_json TEXT;")?;
184	    }
185	
186	    Ok(())
187	}
188	
189	fn insert_journal_event(
190	    tx: &rusqlite::Transaction<'_>,
191	    task: &TaskId,
192	    event: &bridge_core::orch::OrchEvent,
193	) -> Result<(), BridgeError> {
194	    let event_json = serde_json::to_string(event).map_err(|_| BridgeError::StoreFailure)?;
195	    tx.execute(
196	        "INSERT INTO task_journal(task_id, seq, event_json) VALUES(?1, ?2, ?3)",
197	        rusqlite::params![task.as_str(), event.seq, event_json],
198	    )
199	    .map_err(|_| BridgeError::StoreFailure)?;
200	    Ok(())
201	}
202	
203	#[async_trait::async_trait]
204	impl SessionStore for SqliteStore {
205	    async fn put(&self, task: &TaskId, session: &SessionId) -> Result<(), BridgeError> {
206	        let conn = self.conn.lock().unwrap();
207	        conn.execute(
208	            "INSERT INTO sessions(task_id, session_id) VALUES(?1, ?2)
209	             ON CONFLICT(task_id) DO UPDATE SET session_id = excluded.session_id",
210	            rusqlite::params![task.as_str(), session.as_str()],
211	        )
212	        .map_err(|_| BridgeError::StoreFailure)?;
213	        Ok(())
214	    }
215	
216	    async fn session_for(&self, task: &TaskId) -> Result<Option<SessionId>, BridgeError> {
217	        let conn = self.conn.lock().unwrap();
218	        let mut stmt = conn
219	            .prepare("SELECT session_id FROM sessions WHERE task_id = ?1")
220	            .map_err(|_| BridgeError::StoreFailure)?;
221	        let mut rows = stmt
222	            .query(rusqlite::params![task.as_str()])
223	            .map_err(|_| BridgeError::StoreFailure)?;
224	        match rows.next().map_err(|_| BridgeError::StoreFailure)? {
225	            None => Ok(None),
226	            Some(row) => {
227	                let sid: Option<String> = row.get(0).map_err(|_| BridgeError::StoreFailure)?;
228	                match sid {
229	                    None => Ok(None),
230	                    Some(s) => Ok(Some(
231	                        SessionId::parse(s).map_err(|_| BridgeError::StoreFailure)?,
232	                    )),
233	                }
234	            }
235	        }
236	    }
237	
238	    async fn put_pending(&self, task: &TaskId, req: &PendingRequest) -> Result<(), BridgeError> {
239	        let kind_str = match req.kind {
240	            PendingKind::Permission => "permission",
