434	pub struct MemoryTaskStore {
435	    /// Coarse guard for Memory fold-input consistency across the split maps.
436	    journal_fold_guard: Mutex<()>,
437	    inner: Mutex<HashMap<String, TaskRecord>>,
438	    batches: Mutex<HashMap<BatchId, BatchRecord>>,
439	    /// Tasks created under S6 code have complete journal coverage from birth.
440	    birth: Mutex<HashSet<String>>,
441	    /// Key: (task_id, node_id) → (output, ok, ts, seq, usage)
442	    checkpoints: Mutex<HashMap<(String, String), CheckpointValue>>,
443	    /// Per-task monotonic seq counter. Key: task_id.
444	    seq_counters: Mutex<HashMap<String, i64>>,
445	    /// Per-task terminal seq. Key: task_id.
446	    terminal_seqs: Mutex<HashMap<String, i64>>,
447	    /// In-progress node starts. Key: (task_id, node_id) → (seq, ts).
448	    starts: Mutex<HashMap<(String, String), (i64, i64)>>,
449	    /// Per-task durable orchestration journal rows. Key: task_id.
450	    journals: Mutex<HashMap<String, Vec<(i64, crate::orch::OrchEvent)>>>,
451	}
452	
453	impl MemoryTaskStore {
454	    pub fn new() -> Self {
455	        Self {
456	            journal_fold_guard: Mutex::new(()),
457	            inner: Mutex::new(HashMap::new()),
458	            batches: Mutex::new(HashMap::new()),
459	            birth: Mutex::new(HashSet::new()),
460	            checkpoints: Mutex::new(HashMap::new()),
461	            seq_counters: Mutex::new(HashMap::new()),
462	            terminal_seqs: Mutex::new(HashMap::new()),
463	            starts: Mutex::new(HashMap::new()),
464	            journals: Mutex::new(HashMap::new()),
465	        }
466	    }
467	
468	    /// Allocate and return the next seq for the given task.
469	    /// Must be called with NO other locks held (takes seq_counters lock internally).
470	    fn next_seq(&self, task_id: &str) -> i64 {
471	        let mut g = self.seq_counters.lock().unwrap();
472	        let seq = g.entry(task_id.to_string()).or_insert(0);
473	        *seq += 1;
474	        *seq
475	    }
476	}
477	
478	#[async_trait::async_trait]
479	impl TaskStore for MemoryTaskStore {
480	    async fn create(&self, rec: &TaskRecord) -> Result<(), BridgeError> {
481	        let _guard = self.journal_fold_guard.lock().unwrap();
482	        let mut g = self.inner.lock().unwrap();
483	        if g.contains_key(rec.id.as_str()) {
484	            return Err(BridgeError::StoreFailure);
485	        }
486	        g.insert(rec.id.as_str().to_string(), rec.clone());
487	        self.birth
488	            .lock()
489	            .unwrap()
490	            .insert(rec.id.as_str().to_string());
491	        Ok(())
492	    }
493	    async fn set_terminal(
494	        &self,
495	        id: &TaskId,
496	        status: TaskRecordStatus,
497	        result: Option<&str>,
498	        error: Option<&str>,
499	        updated_ms: i64,
500	    ) -> Result<(), BridgeError> {
501	        let _guard = self.journal_fold_guard.lock().unwrap();
502	        let mut g = self.inner.lock().unwrap();
503	        let row = g.get_mut(id.as_str()).ok_or(BridgeError::StoreFailure)?;
504	        row.status = status;
505	        row.result = result.map(|s| s.to_string());
506	        row.error = error.map(|s| s.to_string());
507	        row.updated_ms = updated_ms;
508	        Ok(())
509	    }
510	    async fn get(&self, id: &TaskId) -> Result<Option<TaskRecord>, BridgeError> {
511	        Ok(self.inner.lock().unwrap().get(id.as_str()).cloned())
512	    }
513	    async fn list(&self, limit: usize) -> Result<Vec<TaskRecord>, BridgeError> {
514	        let g = self.inner.lock().unwrap();
515	        let mut v: Vec<TaskRecord> = g.values().cloned().collect();
516	        v.sort_by(|a, b| b.updated_ms.cmp(&a.updated_ms));
517	        v.truncate(limit);
518	        Ok(v)
519	    }
520	    async fn sweep_interrupted(&self, updated_ms: i64) -> Result<u64, BridgeError> {
521	        let _guard = self.journal_fold_guard.lock().unwrap();
522	        let mut g = self.inner.lock().unwrap();
523	        let mut n = 0;
524	        for row in g.values_mut() {
525	            if row.status == TaskRecordStatus::Working {
526	                row.status = TaskRecordStatus::Interrupted;
527	                row.error = Some("interrupted (serve restarted)".into());
528	                row.updated_ms = updated_ms;
529	                n += 1;
530	            }
531	        }
532	        Ok(n)
533	    }
534	    async fn cancel_if_working(&self, id: &TaskId, updated_ms: i64) -> Result<bool, BridgeError> {
535	        let _guard = self.journal_fold_guard.lock().unwrap();
536	        let mut g = self.inner.lock().unwrap();
537	        match g.get_mut(id.as_str()) {
538	            Some(row) if row.status == TaskRecordStatus::Working => {
539	                row.status = TaskRecordStatus::Canceled;
540	                row.updated_ms = updated_ms;
541	                Ok(true)
542	            }
543	            _ => Ok(false), // missing or already terminal — do not clobber
544	        }
545	    }
546	    async fn put_node_checkpoint(
547	        &self,
548	        task: &TaskId,
549	        node: &NodeId,
550	        output: &str,
551	        ok: bool,
552	        ts: i64,
553	    ) -> Result<(), BridgeError> {
554	        // The task must exist — matches the SQLite FK (foreign_keys=ON) contract.
555	        {
556	            let inner = self.inner.lock().unwrap();
557	            if !inner.contains_key(task.as_str()) {
558	                return Err(BridgeError::StoreFailure);
559	            }
560	        } // drop inner guard before locking checkpoints to avoid lock-order deadlock
561	        let mut g = self.checkpoints.lock().unwrap();
562	        let key = (task.as_str().to_string(), node.as_str().to_string());
563	        if g.contains_key(&key) {
564	            return Err(BridgeError::StoreFailure);
565	        }
566	        g.insert(key, (output.to_string(), ok, ts, 0, None));
567	        Ok(())
568	    }
569	    async fn node_checkpoints(
570	        &self,
571	        task: &TaskId,
572	    ) -> Result<Vec<(NodeId, String, bool, Option<crate::orch::UsageSnapshot>)>, BridgeError> {
573	        let g = self.checkpoints.lock().unwrap();
574	        let mut out = Vec::new();
575	        for ((tid, nid), (output, ok, _ts, _seq, usage)) in g.iter() {
576	            if tid == task.as_str() {
577	                let node = NodeId::parse(nid).map_err(|_| BridgeError::StoreFailure)?;
578	                out.push((node, output.clone(), *ok, usage.clone()));
579	            }
580	        }
581	        Ok(out)
582	    }
583	    async fn claim_resume_attempt(
584	        &self,
585	        task: &TaskId,
586	        cap: u32,
587	        now_ms: i64,
588	    ) -> Result<ResumeClaim, BridgeError> {
589	        let mut g = self.inner.lock().unwrap();
590	        let row = g.get_mut(task.as_str()).ok_or(BridgeError::StoreFailure)?;
591	        if row.resume_attempts >= cap {
592	            return Ok(ResumeClaim::Exhausted);
593	        }
594	        row.resume_attempts += 1;
595	        row.updated_ms = now_ms; // last_resume_ms is folded into updated_ms for the in-memory store; the SQLite store has the dedicated column.
596	        Ok(ResumeClaim::Resumable {
597	            attempt: row.resume_attempts,
598	        })
599	    }
600	    async fn working_tasks(&self) -> Result<Vec<TaskRecord>, BridgeError> {
601	        let g = self.inner.lock().unwrap();
602	        Ok(g.values()
603	            .filter(|r| r.status == TaskRecordStatus::Working)
604	            .cloned()
605	            .collect())
606	    }
607	
608	    async fn create_batch(&self, rec: &BatchRecord) -> Result<(), BridgeError> {
609	        let mut g = self.batches.lock().unwrap();
610	        if g.contains_key(&rec.id) {
611	            return Err(BridgeError::StoreFailure);
612	        }
613	        g.insert(rec.id.clone(), rec.clone());
614	        Ok(())
615	    }
616	
617	    async fn get_batch(&self, id: &BatchId) -> Result<Option<BatchRecord>, BridgeError> {
618	        Ok(self.batches.lock().unwrap().get(id).cloned())
619	    }
620	
621	    async fn list_batches(&self, limit: usize) -> Result<Vec<BatchRecord>, BridgeError> {
622	        let g = self.batches.lock().unwrap();
623	        let mut v: Vec<BatchRecord> = g.values().cloned().collect();
624	        v.sort_by(|a, b| b.updated_ms.cmp(&a.updated_ms));
625	        v.truncate(limit);
626	        Ok(v)
627	    }
628	
629	    async fn active_batches(&self) -> Result<Vec<BatchRecord>, BridgeError> {
630	        let g = self.batches.lock().unwrap();
631	        Ok(g.values()
632	            .filter(|r| matches!(r.status, BatchStatus::Working | BatchStatus::Canceling))
633	            .cloned()
634	            .collect())
635	    }
636	
637	    async fn batch_children(&self, id: &BatchId) -> Result<Vec<TaskRecord>, BridgeError> {
638	        let g = self.inner.lock().unwrap();
639	        Ok(g.values()
640	            .filter(|r| r.batch_id.as_ref() == Some(id))
641	            .cloned()
642	            .collect())
643	    }
644	
645	    async fn claim_batch_child(
646	        &self,
647	        batch: &BatchId,
648	        item: &str,
649	        rec: &TaskRecord,
650	    ) -> Result<ChildClaim, BridgeError> {
651	        let _guard = self.journal_fold_guard.lock().unwrap();
652	        let mut g = self.inner.lock().unwrap();
653	        if let Some(existing) = g
654	            .values()
655	            .find(|r| r.batch_id.as_ref() == Some(batch) && r.item_id.as_deref() == Some(item))
656	        {
657	            return Ok(if existing.status == TaskRecordStatus::Working {
658	                ChildClaim::ExistingWorking
659	            } else {
660	                ChildClaim::ExistingTerminal
661	            });
662	        }
663	        if g.contains_key(rec.id.as_str()) {
664	            return Err(BridgeError::StoreFailure);
665	        }
666	        let mut rec = rec.clone();
667	        rec.batch_id = Some(batch.clone());
668	        rec.item_id = Some(item.to_string());
669	        let task_id = rec.id.as_str().to_string();
670	        g.insert(task_id.clone(), rec);
671	        self.birth.lock().unwrap().insert(task_id);
672	        Ok(ChildClaim::Created)
673	    }
674	
675	    async fn cancel_batch_if_working(&self, id: &BatchId, ts: i64) -> Result<bool, BridgeError> {
676	        let mut g = self.batches.lock().unwrap();
677	        match g.get_mut(id) {
678	            Some(row) if row.status == BatchStatus::Working => {
679	                row.status = BatchStatus::Canceling;
680	                row.updated_ms = ts;
681	                Ok(true)
682	            }
683	            _ => Ok(false),
684	        }
685	    }
686	
687	    async fn settle_batch_if_status(
688	        &self,
689	        id: &BatchId,
690	        expect: BatchStatus,
691	        new: BatchStatus,
692	        ts: i64,
693	    ) -> Result<bool, BridgeError> {
694	        let mut g = self.batches.lock().unwrap();
695	        match g.get_mut(id) {
696	            Some(row) if row.status == expect => {
697	                row.status = new;
698	                row.updated_ms = ts;
699	                Ok(true)
700	            }
701	            _ => Ok(false),
702	        }
703	    }
704	
705	    async fn fail_batch_if_status(
706	        &self,
707	        id: &BatchId,
708	        expect: BatchStatus,
709	        error: &str,
710	        ts: i64,
711	    ) -> Result<bool, BridgeError> {
712	        let mut g = self.batches.lock().unwrap();
713	        match g.get_mut(id) {
714	            Some(row) if row.status == expect => {
715	                row.status = BatchStatus::Failed;
716	                row.error = Some(error.to_string());
717	                row.updated_ms = ts;
718	                Ok(true)
719	            }
720	            _ => Ok(false),
721	        }
722	    }
723	
724	    async fn record_node_started(
725	        &self,
726	        task: &TaskId,
727	        node: &NodeId,
728	        operation_id: &OperationId,
729	        ts: i64,
730	    ) -> Result<i64, BridgeError> {
731	        let _guard = self.journal_fold_guard.lock().unwrap();
732	        // Task must exist.
733	        {
734	            let inner = self.inner.lock().unwrap();
735	            if !inner.contains_key(task.as_str()) {
736	                return Err(BridgeError::StoreFailure);
737	            }
738	        }
739	        let seq = self.next_seq(task.as_str());
